BEGIN;

CREATE TABLE alembic_version (
    version_num VARCHAR(32) NOT NULL, 
    CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);

-- Running upgrade  -> 0001

CREATE TABLE assessment_versions (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    version INTEGER NOT NULL, 
    title VARCHAR(120) NOT NULL, 
    is_active BOOLEAN DEFAULT false NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_assessment_versions PRIMARY KEY (id), 
    CONSTRAINT ck_assessment_versions_version_positive CHECK (version >= 1), 
    CONSTRAINT uq_assessment_versions_version UNIQUE (version)
);

CREATE UNIQUE INDEX uq_assessment_versions_single_active ON assessment_versions (is_active) WHERE is_active;

CREATE TABLE habit_templates (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    code VARCHAR(64) NOT NULL, 
    version INTEGER DEFAULT '1' NOT NULL, 
    title VARCHAR(120) NOT NULL, 
    description TEXT, 
    category VARCHAR(20) NOT NULL, 
    goal_type VARCHAR(10) NOT NULL, 
    target_value NUMERIC(12, 3), 
    unit VARCHAR(32), 
    default_weekly_target_count SMALLINT NOT NULL, 
    difficulty SMALLINT NOT NULL, 
    is_active BOOLEAN DEFAULT true NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_habit_templates PRIMARY KEY (id), 
    CONSTRAINT ck_habit_templates_goal_shape CHECK ((goal_type = 'binary' AND target_value IS NULL AND unit IS NULL) OR (goal_type = 'quantity' AND target_value IS NOT NULL AND target_value > 0 AND unit IS NOT NULL) OR (goal_type = 'duration' AND target_value IS NOT NULL AND target_value > 0 AND unit = 'minutes')), 
    CONSTRAINT ck_habit_templates_category_valid CHECK (category IN ('sleep', 'hydration', 'nutrition', 'activity', 'focus', 'wellbeing', 'other')), 
    CONSTRAINT ck_habit_templates_goal_type_valid CHECK (goal_type IN ('binary', 'quantity', 'duration')), 
    CONSTRAINT ck_habit_templates_weekly_target_range CHECK (default_weekly_target_count BETWEEN 1 AND 7), 
    CONSTRAINT ck_habit_templates_difficulty_range CHECK (difficulty BETWEEN 1 AND 5), 
    CONSTRAINT ck_habit_templates_version_positive CHECK (version >= 1), 
    CONSTRAINT uq_habit_templates_code_version UNIQUE (code, version)
);

CREATE INDEX ix_habit_templates_active_category ON habit_templates (is_active, category);

CREATE TABLE profiles (
    id UUID NOT NULL, 
    display_name VARCHAR(100), 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_profiles PRIMARY KEY (id)
);

CREATE TABLE xp_rules (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    rule_code VARCHAR(40) NOT NULL, 
    effective_from DATE NOT NULL, 
    source_type VARCHAR(12) NOT NULL, 
    xp_amount INTEGER NOT NULL, 
    daily_cap INTEGER, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_xp_rules PRIMARY KEY (id), 
    CONSTRAINT ck_xp_rules_source_type_valid CHECK (source_type IN ('habit_log', 'mission_log', 'task')), 
    CONSTRAINT ck_xp_rules_daily_cap_nonneg CHECK (daily_cap IS NULL OR daily_cap >= 0), 
    CONSTRAINT ck_xp_rules_xp_amount_nonneg CHECK (xp_amount >= 0), 
    CONSTRAINT uq_xp_rules_code_from UNIQUE (rule_code, effective_from)
);

CREATE TABLE assessment_questions (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    assessment_version_id UUID NOT NULL, 
    question_key VARCHAR(64) NOT NULL, 
    domain VARCHAR(20) NOT NULL, 
    prompt TEXT NOT NULL, 
    answer_type VARCHAR(16) NOT NULL, 
    options JSONB, 
    position INTEGER NOT NULL, 
    is_required BOOLEAN DEFAULT true NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_assessment_questions PRIMARY KEY (id), 
    CONSTRAINT ck_assessment_questions_answer_type_valid CHECK (answer_type IN ('scale', 'number', 'single_choice', 'multi_choice', 'text')), 
    CONSTRAINT ck_assessment_questions_domain_valid CHECK (domain IN ('sleep', 'hydration', 'nutrition', 'activity', 'focus', 'wellbeing', 'goals', 'availability')), 
    CONSTRAINT ck_assessment_questions_position_nonneg CHECK (position >= 0), 
    CONSTRAINT fk_assessment_questions_assessment_version_id_assessmen_bea1 FOREIGN KEY(assessment_version_id) REFERENCES assessment_versions (id) ON DELETE RESTRICT, 
    CONSTRAINT uq_assessment_questions_version_pos UNIQUE (assessment_version_id, position), 
    CONSTRAINT uq_assessment_questions_version_key UNIQUE (assessment_version_id, question_key), 
    CONSTRAINT uq_assessment_questions_id_version UNIQUE (id, assessment_version_id)
);

CREATE TABLE assessments (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    user_id UUID NOT NULL, 
    assessment_version_id UUID NOT NULL, 
    status VARCHAR(12) DEFAULT 'in_progress' NOT NULL, 
    started_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    completed_at TIMESTAMP WITH TIME ZONE, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_assessments PRIMARY KEY (id), 
    CONSTRAINT ck_assessments_completed_at_matches_status CHECK ((status = 'completed') = (completed_at IS NOT NULL)), 
    CONSTRAINT ck_assessments_status_valid CHECK (status IN ('in_progress', 'completed', 'abandoned')), 
    CONSTRAINT fk_assessments_assessment_version_id_assessment_versions FOREIGN KEY(assessment_version_id) REFERENCES assessment_versions (id) ON DELETE RESTRICT, 
    CONSTRAINT fk_assessments_user_id_profiles FOREIGN KEY(user_id) REFERENCES profiles (id) ON DELETE RESTRICT, 
    CONSTRAINT uq_assessments_id_version UNIQUE (id, assessment_version_id), 
    CONSTRAINT uq_assessments_id_user_id UNIQUE (id, user_id)
);

CREATE INDEX ix_assessments_assessment_version_id ON assessments (assessment_version_id);

CREATE INDEX ix_assessments_user_id_started_at ON assessments (user_id, started_at);

CREATE UNIQUE INDEX uq_assessments_user_in_progress ON assessments (user_id) WHERE status = 'in_progress';

CREATE TABLE habits (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    user_id UUID NOT NULL, 
    name VARCHAR(120) NOT NULL, 
    description TEXT, 
    category VARCHAR(20) NOT NULL, 
    origin VARCHAR(10) DEFAULT 'user' NOT NULL, 
    source_template_id UUID, 
    end_date DATE, 
    status VARCHAR(10) DEFAULT 'active' NOT NULL, 
    archived_at TIMESTAMP WITH TIME ZONE, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_habits PRIMARY KEY (id), 
    CONSTRAINT ck_habits_archived_at_matches_status CHECK ((status = 'archived') = (archived_at IS NOT NULL)), 
    CONSTRAINT ck_habits_category_valid CHECK (category IN ('sleep', 'hydration', 'nutrition', 'activity', 'focus', 'wellbeing', 'other')), 
    CONSTRAINT ck_habits_template_only_if_system CHECK (origin = 'system' OR source_template_id IS NULL), 
    CONSTRAINT ck_habits_origin_valid CHECK (origin IN ('user', 'system')), 
    CONSTRAINT ck_habits_status_valid CHECK (status IN ('active', 'archived')), 
    CONSTRAINT fk_habits_source_template_id_habit_templates FOREIGN KEY(source_template_id) REFERENCES habit_templates (id) ON DELETE RESTRICT, 
    CONSTRAINT fk_habits_user_id_profiles FOREIGN KEY(user_id) REFERENCES profiles (id) ON DELETE RESTRICT, 
    CONSTRAINT uq_habits_id_user_id UNIQUE (id, user_id)
);

CREATE INDEX ix_habits_source_template_id ON habits (source_template_id);

CREATE INDEX ix_habits_user_id_status ON habits (user_id, status);

CREATE UNIQUE INDEX uq_habits_user_active_name ON habits (user_id, lower(name)) WHERE status = 'active';

CREATE TABLE projects (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    user_id UUID NOT NULL, 
    name VARCHAR(120) NOT NULL, 
    description TEXT, 
    status VARCHAR(10) DEFAULT 'active' NOT NULL, 
    archived_at TIMESTAMP WITH TIME ZONE, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_projects PRIMARY KEY (id), 
    CONSTRAINT ck_projects_archived_at_matches_status CHECK ((status = 'archived') = (archived_at IS NOT NULL)), 
    CONSTRAINT ck_projects_status_valid CHECK (status IN ('active', 'completed', 'archived')), 
    CONSTRAINT fk_projects_user_id_profiles FOREIGN KEY(user_id) REFERENCES profiles (id) ON DELETE RESTRICT, 
    CONSTRAINT uq_projects_id_user_id UNIQUE (id, user_id)
);

CREATE INDEX ix_projects_user_id_status ON projects (user_id, status);

CREATE UNIQUE INDEX uq_projects_user_open_name ON projects (user_id, lower(name)) WHERE status <> 'archived';

CREATE TABLE user_game_profiles (
    user_id UUID NOT NULL, 
    total_xp BIGINT DEFAULT '0' NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_user_game_profiles PRIMARY KEY (user_id), 
    CONSTRAINT ck_user_game_profiles_total_xp_nonneg CHECK (total_xp >= 0), 
    CONSTRAINT fk_user_game_profiles_user_id_profiles FOREIGN KEY(user_id) REFERENCES profiles (id) ON DELETE RESTRICT
);

CREATE TABLE user_settings (
    user_id UUID NOT NULL, 
    timezone VARCHAR(64) DEFAULT 'UTC' NOT NULL, 
    language VARCHAR(10) DEFAULT 'es' NOT NULL, 
    theme VARCHAR(10) DEFAULT 'system' NOT NULL, 
    week_start_day SMALLINT DEFAULT '1' NOT NULL, 
    time_format VARCHAR(3) DEFAULT '24h' NOT NULL, 
    notifications_enabled BOOLEAN DEFAULT true NOT NULL, 
    daily_reminder_time TIME WITHOUT TIME ZONE, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_user_settings PRIMARY KEY (user_id), 
    CONSTRAINT ck_user_settings_language_format CHECK (language ~ '^[a-z]{2}(-[A-Z]{2})?$'), 
    CONSTRAINT ck_user_settings_theme_valid CHECK (theme IN ('light', 'dark', 'system')), 
    CONSTRAINT ck_user_settings_time_format_valid CHECK (time_format IN ('12h', '24h')), 
    CONSTRAINT ck_user_settings_week_start_day_range CHECK (week_start_day BETWEEN 1 AND 7), 
    CONSTRAINT fk_user_settings_user_id_profiles FOREIGN KEY(user_id) REFERENCES profiles (id) ON DELETE RESTRICT
);

CREATE TABLE assessment_answers (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    user_id UUID NOT NULL, 
    assessment_id UUID NOT NULL, 
    assessment_version_id UUID NOT NULL, 
    question_id UUID NOT NULL, 
    value_number NUMERIC(12, 3), 
    value_text TEXT, 
    value_options JSONB, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_assessment_answers PRIMARY KEY (id), 
    CONSTRAINT ck_assessment_answers_exactly_one_value CHECK (num_nonnulls(value_number, value_text, value_options) = 1), 
    CONSTRAINT fk_assessment_answers_assessment_version FOREIGN KEY(assessment_id, assessment_version_id) REFERENCES assessments (id, assessment_version_id) ON DELETE RESTRICT, 
    CONSTRAINT fk_assessment_answers_assessment_owner FOREIGN KEY(assessment_id, user_id) REFERENCES assessments (id, user_id) ON DELETE RESTRICT, 
    CONSTRAINT fk_assessment_answers_question_in_version FOREIGN KEY(question_id, assessment_version_id) REFERENCES assessment_questions (id, assessment_version_id) ON DELETE RESTRICT, 
    CONSTRAINT uq_assessment_answers_assessment_question UNIQUE (assessment_id, question_id)
);

CREATE INDEX ix_assessment_answers_question_id ON assessment_answers (question_id);

CREATE INDEX ix_assessment_answers_user_id ON assessment_answers (user_id);

CREATE TABLE habit_versions (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    habit_id UUID NOT NULL, 
    effective_from DATE NOT NULL, 
    goal_type VARCHAR(10) NOT NULL, 
    target_value NUMERIC(12, 3), 
    unit VARCHAR(32), 
    frequency_type VARCHAR(16) NOT NULL, 
    weekly_target_count SMALLINT, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_habit_versions PRIMARY KEY (id), 
    CONSTRAINT ck_habit_versions_weekly_target_shape CHECK ((frequency_type = 'times_per_week' AND weekly_target_count IS NOT NULL AND weekly_target_count BETWEEN 1 AND 7) OR (frequency_type <> 'times_per_week' AND weekly_target_count IS NULL)), 
    CONSTRAINT ck_habit_versions_goal_shape CHECK ((goal_type = 'binary' AND target_value IS NULL AND unit IS NULL) OR (goal_type = 'quantity' AND target_value IS NOT NULL AND target_value > 0 AND unit IS NOT NULL) OR (goal_type = 'duration' AND target_value IS NOT NULL AND target_value > 0 AND unit = 'minutes')), 
    CONSTRAINT ck_habit_versions_frequency_type_valid CHECK (frequency_type IN ('daily', 'weekdays', 'times_per_week')), 
    CONSTRAINT ck_habit_versions_goal_type_valid CHECK (goal_type IN ('binary', 'quantity', 'duration')), 
    CONSTRAINT fk_habit_versions_habit_id_habits FOREIGN KEY(habit_id) REFERENCES habits (id) ON DELETE RESTRICT, 
    CONSTRAINT uq_habit_versions_habit_from UNIQUE (habit_id, effective_from), 
    CONSTRAINT uq_habit_versions_id_habit_id UNIQUE (id, habit_id)
);

CREATE TABLE improvement_plans (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    user_id UUID NOT NULL, 
    assessment_id UUID NOT NULL, 
    status VARCHAR(10) DEFAULT 'active' NOT NULL, 
    started_on DATE NOT NULL, 
    ended_on DATE, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_improvement_plans PRIMARY KEY (id), 
    CONSTRAINT ck_improvement_plans_ended_on_matches_status CHECK ((status = 'active') = (ended_on IS NULL)), 
    CONSTRAINT ck_improvement_plans_status_valid CHECK (status IN ('active', 'completed', 'archived')), 
    CONSTRAINT ck_improvement_plans_ended_after_started CHECK (ended_on IS NULL OR ended_on >= started_on), 
    CONSTRAINT fk_improvement_plans_assessment_owner FOREIGN KEY(assessment_id, user_id) REFERENCES assessments (id, user_id) ON DELETE RESTRICT, 
    CONSTRAINT fk_improvement_plans_user_id_profiles FOREIGN KEY(user_id) REFERENCES profiles (id) ON DELETE RESTRICT, 
    CONSTRAINT uq_improvement_plans_assessment_id UNIQUE (assessment_id), 
    CONSTRAINT uq_improvement_plans_id_user_id UNIQUE (id, user_id)
);

CREATE INDEX ix_improvement_plans_user_id_status ON improvement_plans (user_id, status);

CREATE UNIQUE INDEX uq_improvement_plans_user_active ON improvement_plans (user_id) WHERE status = 'active';

CREATE TABLE tasks (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    user_id UUID NOT NULL, 
    project_id UUID, 
    title VARCHAR(200) NOT NULL, 
    description TEXT, 
    priority VARCHAR(10) DEFAULT 'medium' NOT NULL, 
    status VARCHAR(12) DEFAULT 'todo' NOT NULL, 
    scheduled_date DATE, 
    due_date DATE, 
    completed_at TIMESTAMP WITH TIME ZONE, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_tasks PRIMARY KEY (id), 
    CONSTRAINT ck_tasks_completed_at_matches_status CHECK ((status = 'done') = (completed_at IS NOT NULL)), 
    CONSTRAINT ck_tasks_priority_valid CHECK (priority IN ('low', 'medium', 'high')), 
    CONSTRAINT ck_tasks_status_valid CHECK (status IN ('todo', 'in_progress', 'done', 'cancelled')), 
    CONSTRAINT ck_tasks_due_after_scheduled CHECK (due_date IS NULL OR scheduled_date IS NULL OR due_date >= scheduled_date), 
    CONSTRAINT fk_tasks_project_owner FOREIGN KEY(project_id, user_id) REFERENCES projects (id, user_id) ON DELETE RESTRICT, 
    CONSTRAINT fk_tasks_user_id_profiles FOREIGN KEY(user_id) REFERENCES profiles (id) ON DELETE RESTRICT, 
    CONSTRAINT uq_tasks_id_user_id UNIQUE (id, user_id)
);

CREATE INDEX ix_tasks_project_id ON tasks (project_id);

CREATE INDEX ix_tasks_user_id_scheduled_date ON tasks (user_id, scheduled_date);

CREATE INDEX ix_tasks_user_id_status ON tasks (user_id, status);

CREATE TABLE habit_logs (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    user_id UUID NOT NULL, 
    habit_id UUID NOT NULL, 
    habit_version_id UUID NOT NULL, 
    occurrence_date DATE NOT NULL, 
    status VARCHAR(10) NOT NULL, 
    value NUMERIC(12, 3), 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_habit_logs PRIMARY KEY (id), 
    CONSTRAINT ck_habit_logs_skipped_has_no_value CHECK (status <> 'skipped' OR value IS NULL), 
    CONSTRAINT ck_habit_logs_status_valid CHECK (status IN ('completed', 'partial', 'skipped')), 
    CONSTRAINT ck_habit_logs_value_nonneg CHECK (value IS NULL OR value >= 0), 
    CONSTRAINT fk_habit_logs_habit_owner FOREIGN KEY(habit_id, user_id) REFERENCES habits (id, user_id) ON DELETE RESTRICT, 
    CONSTRAINT fk_habit_logs_version_of_habit FOREIGN KEY(habit_version_id, habit_id) REFERENCES habit_versions (id, habit_id) ON DELETE RESTRICT, 
    CONSTRAINT uq_habit_logs_habit_date UNIQUE (habit_id, occurrence_date), 
    CONSTRAINT uq_habit_logs_id_user_id UNIQUE (id, user_id)
);

CREATE INDEX ix_habit_logs_habit_version_id ON habit_logs (habit_version_id);

CREATE INDEX ix_habit_logs_user_id_occurrence_date ON habit_logs (user_id, occurrence_date);

CREATE TABLE habit_version_days (
    habit_version_id UUID NOT NULL, 
    weekday SMALLINT NOT NULL, 
    CONSTRAINT pk_habit_version_days PRIMARY KEY (habit_version_id, weekday), 
    CONSTRAINT ck_habit_version_days_weekday_range CHECK (weekday BETWEEN 1 AND 7), 
    CONSTRAINT fk_habit_version_days_habit_version_id_habit_versions FOREIGN KEY(habit_version_id) REFERENCES habit_versions (id) ON DELETE CASCADE
);

CREATE TABLE missions (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    user_id UUID NOT NULL, 
    plan_id UUID NOT NULL, 
    habit_template_id UUID NOT NULL, 
    week_start DATE NOT NULL, 
    weekly_target_count SMALLINT NOT NULL, 
    target_value NUMERIC(12, 3), 
    unit VARCHAR(32), 
    status VARCHAR(12) DEFAULT 'active' NOT NULL, 
    adapted_from_mission_id UUID, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_missions PRIMARY KEY (id), 
    CONSTRAINT ck_missions_status_valid CHECK (status IN ('active', 'completed', 'abandoned', 'superseded')), 
    CONSTRAINT ck_missions_target_value_positive CHECK (target_value IS NULL OR target_value > 0), 
    CONSTRAINT ck_missions_weekly_target_range CHECK (weekly_target_count BETWEEN 1 AND 7), 
    CONSTRAINT fk_missions_adapted_from_owner FOREIGN KEY(adapted_from_mission_id, user_id) REFERENCES missions (id, user_id) ON DELETE RESTRICT, 
    CONSTRAINT fk_missions_habit_template_id_habit_templates FOREIGN KEY(habit_template_id) REFERENCES habit_templates (id) ON DELETE RESTRICT, 
    CONSTRAINT fk_missions_plan_owner FOREIGN KEY(plan_id, user_id) REFERENCES improvement_plans (id, user_id) ON DELETE RESTRICT, 
    CONSTRAINT uq_missions_id_user_id UNIQUE (id, user_id), 
    CONSTRAINT uq_missions_plan_template_week UNIQUE (plan_id, habit_template_id, week_start)
);

CREATE INDEX ix_missions_adapted_from_mission_id ON missions (adapted_from_mission_id);

CREATE INDEX ix_missions_habit_template_id ON missions (habit_template_id);

CREATE INDEX ix_missions_plan_id ON missions (plan_id);

CREATE INDEX ix_missions_user_id_status ON missions (user_id, status);

CREATE INDEX ix_missions_user_id_week_start ON missions (user_id, week_start);

CREATE TABLE task_checklist_items (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    task_id UUID NOT NULL, 
    title VARCHAR(200) NOT NULL, 
    is_done BOOLEAN DEFAULT false NOT NULL, 
    position INTEGER NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_task_checklist_items PRIMARY KEY (id), 
    CONSTRAINT ck_task_checklist_items_position_nonneg CHECK (position >= 0), 
    CONSTRAINT fk_task_checklist_items_task_id_tasks FOREIGN KEY(task_id) REFERENCES tasks (id) ON DELETE CASCADE, 
    CONSTRAINT uq_task_checklist_items_task_position UNIQUE (task_id, position) DEFERRABLE INITIALLY DEFERRED
);

CREATE TABLE weekly_reviews (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    user_id UUID NOT NULL, 
    plan_id UUID NOT NULL, 
    week_start DATE NOT NULL, 
    perceived_difficulty SMALLINT NOT NULL, 
    energy_level SMALLINT NOT NULL, 
    notes TEXT, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_weekly_reviews PRIMARY KEY (id), 
    CONSTRAINT ck_weekly_reviews_energy_range CHECK (energy_level BETWEEN 1 AND 5), 
    CONSTRAINT ck_weekly_reviews_difficulty_range CHECK (perceived_difficulty BETWEEN 1 AND 5), 
    CONSTRAINT fk_weekly_reviews_plan_owner FOREIGN KEY(plan_id, user_id) REFERENCES improvement_plans (id, user_id) ON DELETE RESTRICT, 
    CONSTRAINT uq_weekly_reviews_plan_week UNIQUE (plan_id, week_start)
);

CREATE INDEX ix_weekly_reviews_user_id ON weekly_reviews (user_id);

CREATE TABLE mission_logs (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    user_id UUID NOT NULL, 
    mission_id UUID NOT NULL, 
    occurrence_date DATE NOT NULL, 
    status VARCHAR(10) NOT NULL, 
    value NUMERIC(12, 3), 
    perceived_difficulty SMALLINT, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_mission_logs PRIMARY KEY (id), 
    CONSTRAINT ck_mission_logs_skipped_has_no_value CHECK (status <> 'skipped' OR value IS NULL), 
    CONSTRAINT ck_mission_logs_status_valid CHECK (status IN ('completed', 'partial', 'skipped')), 
    CONSTRAINT ck_mission_logs_difficulty_range CHECK (perceived_difficulty IS NULL OR perceived_difficulty BETWEEN 1 AND 5), 
    CONSTRAINT ck_mission_logs_value_nonneg CHECK (value IS NULL OR value >= 0), 
    CONSTRAINT fk_mission_logs_mission_owner FOREIGN KEY(mission_id, user_id) REFERENCES missions (id, user_id) ON DELETE RESTRICT, 
    CONSTRAINT uq_mission_logs_id_user_id UNIQUE (id, user_id), 
    CONSTRAINT uq_mission_logs_mission_date UNIQUE (mission_id, occurrence_date)
);

CREATE INDEX ix_mission_logs_user_id_occurrence_date ON mission_logs (user_id, occurrence_date);

CREATE TABLE xp_transactions (
    id UUID DEFAULT gen_random_uuid() NOT NULL, 
    user_id UUID NOT NULL, 
    xp_rule_id UUID NOT NULL, 
    event_type VARCHAR(16) DEFAULT 'completion' NOT NULL, 
    habit_log_id UUID, 
    mission_log_id UUID, 
    task_id UUID, 
    amount INTEGER NOT NULL, 
    award_date DATE NOT NULL, 
    idempotency_key VARCHAR(120) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    CONSTRAINT pk_xp_transactions PRIMARY KEY (id), 
    CONSTRAINT ck_xp_transactions_event_type_valid CHECK (event_type IN ('completion')), 
    CONSTRAINT ck_xp_transactions_amount_nonneg CHECK (amount >= 0), 
    CONSTRAINT ck_xp_transactions_exactly_one_source CHECK (num_nonnulls(habit_log_id, mission_log_id, task_id) = 1), 
    CONSTRAINT fk_xp_transactions_habit_log_owner FOREIGN KEY(habit_log_id, user_id) REFERENCES habit_logs (id, user_id) ON DELETE RESTRICT, 
    CONSTRAINT fk_xp_transactions_mission_log_owner FOREIGN KEY(mission_log_id, user_id) REFERENCES mission_logs (id, user_id) ON DELETE RESTRICT, 
    CONSTRAINT fk_xp_transactions_task_owner FOREIGN KEY(task_id, user_id) REFERENCES tasks (id, user_id) ON DELETE RESTRICT, 
    CONSTRAINT fk_xp_transactions_user_id_profiles FOREIGN KEY(user_id) REFERENCES profiles (id) ON DELETE RESTRICT, 
    CONSTRAINT fk_xp_transactions_xp_rule_id_xp_rules FOREIGN KEY(xp_rule_id) REFERENCES xp_rules (id) ON DELETE RESTRICT, 
    CONSTRAINT uq_xp_transactions_habit_log_event UNIQUE (habit_log_id, event_type), 
    CONSTRAINT uq_xp_transactions_mission_log_event UNIQUE (mission_log_id, event_type), 
    CONSTRAINT uq_xp_transactions_task_event UNIQUE (task_id, event_type), 
    CONSTRAINT uq_xp_transactions_user_key UNIQUE (user_id, idempotency_key)
);

CREATE INDEX ix_xp_transactions_user_id_award_date ON xp_transactions (user_id, award_date);

CREATE INDEX ix_xp_transactions_user_id_created_at ON xp_transactions (user_id, created_at);

CREATE INDEX ix_xp_transactions_xp_rule_id ON xp_transactions (xp_rule_id);

CREATE FUNCTION atelier_xp_transactions_append_only() RETURNS trigger
    LANGUAGE plpgsql AS $$
    BEGIN
        RAISE EXCEPTION 'xp_transactions is append-only: % is not allowed', TG_OP
            USING ERRCODE = 'integrity_constraint_violation';
    END
    $$;

CREATE TRIGGER trg_xp_transactions_append_only
        BEFORE UPDATE OR DELETE ON xp_transactions
        FOR EACH ROW EXECUTE FUNCTION atelier_xp_transactions_append_only();

CREATE FUNCTION atelier_habit_versions_guard() RETURNS trigger
    LANGUAGE plpgsql AS $$
    DECLARE
        habit_end date;
    BEGIN
        IF TG_OP = 'UPDATE' THEN
            IF NEW.habit_id IS DISTINCT FROM OLD.habit_id THEN
                RAISE EXCEPTION 'habit_versions.habit_id is immutable'
                    USING ERRCODE = 'check_violation';
            END IF;
            IF NEW.effective_from IS NOT DISTINCT FROM OLD.effective_from
               AND NEW.goal_type IS NOT DISTINCT FROM OLD.goal_type
               AND NEW.target_value IS NOT DISTINCT FROM OLD.target_value
               AND NEW.unit IS NOT DISTINCT FROM OLD.unit
               AND NEW.frequency_type IS NOT DISTINCT FROM OLD.frequency_type
               AND NEW.weekly_target_count IS NOT DISTINCT FROM OLD.weekly_target_count THEN
                RETURN NEW;  -- nothing semantic changed (e.g. only updated_at)
            END IF;
            IF EXISTS (SELECT 1 FROM habit_logs WHERE habit_version_id = OLD.id) THEN
                RAISE EXCEPTION 'habit version % is referenced by logs and is immutable', OLD.id
                    USING ERRCODE = 'check_violation';
            END IF;
        END IF;

        -- Serialize with log inserts (they take FOR SHARE) and other version changes.
        SELECT end_date INTO habit_end FROM habits WHERE id = NEW.habit_id FOR UPDATE;

        IF habit_end IS NOT NULL AND NEW.effective_from > habit_end THEN
            RAISE EXCEPTION 'version effective_from % is after the habit end_date %',
                NEW.effective_from, habit_end USING ERRCODE = 'check_violation';
        END IF;

        IF EXISTS (
            SELECT 1 FROM habit_logs
            WHERE habit_id = NEW.habit_id AND occurrence_date >= NEW.effective_from
        ) THEN
            RAISE EXCEPTION 'retroactive version change rejected: habit % has logs on or after %',
                NEW.habit_id, NEW.effective_from USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END
    $$;

CREATE TRIGGER trg_habit_versions_guard
        BEFORE INSERT OR UPDATE ON habit_versions
        FOR EACH ROW EXECUTE FUNCTION atelier_habit_versions_guard();

CREATE FUNCTION atelier_habit_version_days_guard() RETURNS trigger
    LANGUAGE plpgsql AS $$
    BEGIN
        IF TG_OP IN ('UPDATE', 'DELETE') THEN
            IF EXISTS (SELECT 1 FROM habit_logs WHERE habit_version_id = OLD.habit_version_id) THEN
                RAISE EXCEPTION 'habit version % has logs; its weekdays are immutable',
                    OLD.habit_version_id USING ERRCODE = 'check_violation';
            END IF;
        END IF;
        IF TG_OP IN ('INSERT', 'UPDATE') THEN
            IF EXISTS (SELECT 1 FROM habit_logs WHERE habit_version_id = NEW.habit_version_id) THEN
                RAISE EXCEPTION 'habit version % has logs; its weekdays are immutable',
                    NEW.habit_version_id USING ERRCODE = 'check_violation';
            END IF;
        END IF;
        IF TG_OP = 'DELETE' THEN
            RETURN OLD;
        END IF;
        RETURN NEW;
    END
    $$;

CREATE TRIGGER trg_habit_version_days_guard
        BEFORE INSERT OR UPDATE OR DELETE ON habit_version_days
        FOR EACH ROW EXECUTE FUNCTION atelier_habit_version_days_guard();

CREATE FUNCTION atelier_habit_logs_guard() RETURNS trigger
    LANGUAGE plpgsql AS $$
    DECLARE
        habit_end date;
        applicable uuid;
    BEGIN
        -- Shared lock: waits while a version change holds FOR UPDATE on the habit row.
        SELECT end_date INTO habit_end FROM habits WHERE id = NEW.habit_id FOR SHARE;

        SELECT id INTO applicable
        FROM habit_versions
        WHERE habit_id = NEW.habit_id AND effective_from <= NEW.occurrence_date
        ORDER BY effective_from DESC
        LIMIT 1;

        IF applicable IS NULL OR applicable <> NEW.habit_version_id THEN
            RAISE EXCEPTION 'occurrence_date % is not governed by habit version %',
                NEW.occurrence_date, NEW.habit_version_id USING ERRCODE = 'check_violation';
        END IF;
        IF habit_end IS NOT NULL AND NEW.occurrence_date > habit_end THEN
            RAISE EXCEPTION 'occurrence_date % is after the habit end_date %',
                NEW.occurrence_date, habit_end USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END
    $$;

CREATE TRIGGER trg_habit_logs_guard
        BEFORE INSERT OR UPDATE OF habit_id, habit_version_id, occurrence_date ON habit_logs
        FOR EACH ROW EXECUTE FUNCTION atelier_habit_logs_guard();

CREATE FUNCTION atelier_habit_requires_version() RETURNS trigger
    LANGUAGE plpgsql AS $$
    DECLARE
        hid uuid;
    BEGIN
        IF TG_TABLE_NAME = 'habits' THEN
            hid := NEW.id;
        ELSE
            hid := OLD.habit_id;
        END IF;
        IF EXISTS (SELECT 1 FROM habits WHERE id = hid)
           AND NOT EXISTS (SELECT 1 FROM habit_versions WHERE habit_id = hid) THEN
            RAISE EXCEPTION 'habit % must have at least one version', hid
                USING ERRCODE = 'check_violation';
        END IF;
        RETURN NULL;
    END
    $$;

CREATE CONSTRAINT TRIGGER trg_habits_require_version
        AFTER INSERT ON habits
        DEFERRABLE INITIALLY DEFERRED
        FOR EACH ROW EXECUTE FUNCTION atelier_habit_requires_version();

CREATE CONSTRAINT TRIGGER trg_habit_versions_keep_one
        AFTER DELETE ON habit_versions
        DEFERRABLE INITIALLY DEFERRED
        FOR EACH ROW EXECUTE FUNCTION atelier_habit_requires_version();

CREATE FUNCTION atelier_mission_logs_guard() RETURNS trigger
    LANGUAGE plpgsql AS $$
    DECLARE
        ws date;
    BEGIN
        SELECT week_start INTO ws FROM missions WHERE id = NEW.mission_id;
        -- If the mission does not exist the foreign key reports the error.
        IF ws IS NOT NULL AND (NEW.occurrence_date < ws OR NEW.occurrence_date > ws + 6) THEN
            RAISE EXCEPTION 'occurrence_date % is outside the mission week starting %',
                NEW.occurrence_date, ws USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END
    $$;

CREATE TRIGGER trg_mission_logs_guard
        BEFORE INSERT OR UPDATE OF mission_id, occurrence_date ON mission_logs
        FOR EACH ROW EXECUTE FUNCTION atelier_mission_logs_guard();

